import logging
from taf.internal.aliasing import aliasing_scope
from taf.internal.sw.dcap.rd.client.dcap_emil_decoder.v1 import ApiException
from taf.sw.dcap.rd.facade import DcapConnection
from taf.internal.robot_typecasts.typecasts import to_boolean
from taf.sw.dcap.rd.exception import NotConnectedException
import urllib3


class rd(object):
    """
    Usage example:
        >>> from taf.sw.dcap.rd import rd
        >>> dcap_object = rd()
        >>> dcap_object.connect_to(host='10.131.230.189', port='8100',  username='dcapuser', password='dcapadmin!',
        >>>                        rd_version='dcapv3', secure=True)
        >>> dcap_object.get_all_bts_info()
        {'alias': 'test_bts',
         'altitude': 850.0,
         'host': '10.41.170.155',
         'id': 1.0,
         'internal_trace_enabled': True,
         'latitude': 13.0474697,
         'longitude': 77.6186067,
         'lteCells': None,
         'mrBtsId': None,
         'name': 'Nokia_FS_NSA_CPRI_TL24',
         'nrCells': None,
         'password': None,
         'port': 443.0,
         'swVersion': None,
         'type': 'GNB',
         'username': None}
    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    lookup_handler, store = aliasing_scope('connection', name=__name__)

    def is_keycloak_enabled(self, alias=None, timeout=60):
        """
        This method is used to check if keycloak is enabled for DCAP UI.

        :param str alias: Default `None`. If no alias is given, the instance alias will be set to `default`.
        :param Union[int,str] timeout: (optional) timeout in seconds for request, default=30s
        """
        raise_custom_exception = False
        try:
            response = self.get_features(connection=alias, timeout=timeout)
            if response:
                logging.info("connection to DCAP is successful")
        except ValueError:
            raise_custom_exception = True
        if raise_custom_exception:
            raise NotConnectedException("keycloak is enabled for this DCAP UI. "
                                        "Please make sure to use the correct credentials.")

    def is_emil_json_server_enabled(self, alias=None, timeout=60):
        """
        This method is used to check if EMIL JSON server is enabled for DCAP.

        :param str alias: Default `None`. If no alias is given, the instance alias will be set to `default`.
        :param Union[int,str] timeout: (optional) timeout in seconds for request, default=30s
        """
        try:
            if self.get_encoded_files_info(connection=alias, timeout=timeout) is not None:
                logging.info("EMIL JSON server is installed as part of DCAP")
                return True
        except ApiException as error:
            if error.status == 404:
                logging.warning("EMIL JSON server is not installed. If you would like to access EMIL API, "
                                "please refer the docs on installation of EMIL JSON server.")
                return False

    def connect_to(self, host, port, username=None, password=None, rd_version='dcapv3', secure=False,
                   alias=None, timeout=60):
        """
        Provides connection to DCAP-LITE.

        :param str host: IP address to proper host, e.g. `127.0.0.1`.
        :param str port: Port for connection to DCAP.
        :param str username: username, default value: None. If user wants to connect DCAP with username
                             please update 'username'='dcapuser'.
        :param str password: password, default value: None. If user wants to connect DCAP with password
                             please update 'password'=dcapadmin!.
        :param str rd_version: RD version used in this library, default value is `dcapv3`
                               If user wants to run keywords from v2 version please pass rd_version=`dcapv2`
                               If user wants to run keywords from v3 version please pass rd_version=`dcapv3`
                               would suggest to use the latest version as those provide more info.
        :param bool secure: If set to `True`, the connection will be realized with use https prefix,
                            else with http, default value is `False`.
        :param str alias: Default `None`. If no alias is given, the instance alias will be set to `default`.
        :param Union[int,str] timeout: (optional) timeout in seconds for request, default=30s

        :return: It returns dcapConnection instance.
        """
        urllib3.disable_warnings()
        self._dcap_connection = DcapConnection(host=host,
                                               port=port,
                                               username=username,
                                               password=password,
                                               rd_version=rd_version,
                                               secure=to_boolean(secure),
                                               timeout=int(timeout))
        self.store.add(self._dcap_connection, alias)
        self.is_keycloak_enabled(alias, timeout)
        self.is_emil_json_server_enabled(alias, timeout)

    @lookup_handler.implicit_lookup
    def create_bts(self, host, port='443', username='Nemuadmin', password='nemuuser', bts_alias='target_bts',
                   credential_region_Id='DEFAULT_CREDENTIALS', connection=None, timeout=30):
        """
        This method is used to create the bts under DCAP-LITE

        :param str host: IP address to proper host, e.g. `127.0.0.1`.
        :param str port: (optional) Port for connection to DCAP, default value is `443`
        :param str username: (optional) Username to authenticate the BTS, default value is `Nemuadmin`
        :param str password: (optional) Password to authenticate the BTS, default value is `nemuuser`
        :param str bts_alias: (optional) alias for bts, default value is `target_bts`
        :param str credential_region_Id: (optional) Unique identifier for credential region,
                                         default value is `DEFAULT_CREDENTIALS`
        :param DcapConnection connection: (optional) Unique identifier for a certain connections.
        :param Union[int,str] timeout: (optional) timeout in seconds for request, default=30s

        :return: It returns dict with operation information: alias, host, port, username, password,
                 lteCells and nrCells.
        """
        return connection.create_bts(host=host, port=port, username=username, password=password,
                                     bts_alias=bts_alias, credential_region_Id=credential_region_Id,
                                     timeout=int(timeout))

    @lookup_handler.implicit_lookup
    def create_multiple_bts(self, bts_info, connection=None, timeout=30):
        """
        This method is used to create multiple bts under DCAP-LITE

        :param array bts_info: An array of dict containing the following fields:
        * **host** (*str*) - The host name of the BTS.
        * **port** (*int*) - The port number used for the BTS connection.
        * **username** (*str*) - The username used for the BTS connection.
        * **password** (*str*) - The password used for the BTS connection.
        * **alias** (*str*) - The alias used for the BTS connection.
        * **credential_region_Id** (*str*) - Unique identifier for credential region

        Example usage:

        ... code-block:: python

        bts_info = [{'host': '10.0.0.1', 'port': 22, 'username': 'user1', 'password': 'password1',
                    'credential_region_Id': 'DEFAULT_CREDENTIALS'},
                    {'host': '10.0.0.2', 'port': 22, 'username': 'user2', 'password': 'password2',
                    'credential_region_Id': 'DEFAULT_CREDENTIALS'}]

        :param DcapConnection connection: (optional) Unique identifier for a certain connections.
        :param Union[int,str] timeout: (optional) timeout in seconds for request, default=30s

        :return: It returns dict with operation information: alias, host, port, username, password,
                 lteCells and nrCells.
        """
        return connection.create_multiple_bts(bts_info=bts_info, timeout=int(timeout))

    @lookup_handler.implicit_lookup
    def delete_bts(self, bts_id=None, connection=None, timeout=30):
        """
        This method is used to delete the bts under DCAP-LITE

        :param str bts_id: bts id which has to be deleted. Id will be returned from create_bts keyword.
        :param DcapConnection connection: (optional) Unique identifier for a certain connections.
        :param Union[int,str] timeout: (optional) timeout in seconds for request, default=30s

        :return: 'OK'.
        """
        return connection.delete_bts(bts_id=bts_id, timeout=int(timeout))

    @lookup_handler.implicit_lookup
    def edit_bts(self, bts_id, host, port='443', username='Nemuadmin', password='nemuuser', bts_alias='target_bts',
                 lte_cells=None, nr_cells=None, connection=None, timeout=30):
        """
        This method is used to create the bts under DCAP-LITE

        :param float or int bts_id: (required)
        :param str host: IP address to proper host, e.g. `127.0.0.1`.
        :param str port: Port for connection to DCAP, default value is `443`
        :param str username: Username to authenticate the BTS, default value is `Nemuadmin`
        :param str password: Password to authenticate the BTS, default value is `nemuuser`
        :param str bts_alias: alias for bts, default value is `target_bts`
        :param str lte_cells: Sets the lte_cells
        :param str nr_cells: Sets the nr_cells
        :param DcapConnection connection: (optional) Unique identifier for a certain connections.
        :param Union[int,str] timeout: (optional) timeout in seconds for request, default=30s

        :return: It returns dict with operation information: alias, host, port, username, password,
                 lteCells and nrCells.
        """
        return connection.edit_bts(bts_id=bts_id, host=host, port=port, username=username, password=password,
                                   bts_alias=bts_alias, lte_cells=lte_cells, nr_cells=nr_cells,
                                   timeout=int(timeout))

    @lookup_handler.implicit_lookup
    def delete_trace(self, trace_id=None, connection=None, timeout=30):
        """
        This method is used to delete the bts trace under DCAP-LITE

        :param str trace_id: trace id which has to be deleted. Id will be returned from start_trace keyword.
        :param DcapConnection connection: (optional) Unique identifier for a certain connections.
        :param Union[int,str] timeout: (optional) timeout in seconds for request, default=30s

        :return: 'OK'.
        """
        return connection.delete_trace(trace_id=trace_id, timeout=int(timeout))

    @lookup_handler.implicit_lookup
    def start_trace(self, bts, tag='start_trace', duration=-1, connection=None, timeout=400, resource_group=None,
                    allow_start_failures=True, force=True, **kwargs):
        """
        This method is used to start trace under DCAP-LITE

        :param list[dict] bts: (required) dict of bts details containing host, username, password and port number to
                          start the trace for single bts.
                          The list of dict bts details containing host, username, password and port number to
                          start the trace for multiple bts.
        :param str tag: the tag of this StartTraceBody. default 'start_trace'
        :param float duration: The duration of this StartTraceBody duration in minutes.default infinite duration
        :param Union[int,str] timeout: (optional) Timeout to wait for "running" state, default=400s
        :param DcapConnection connection: (optional) Unique identifier for a certain connections.
        :param str kwargs:  supported params are as below:
        :param bool force: signifying whether the trace should force a shutdown of any previously running traces.
                       Defaults to true. If the trace startup finds an ongoing trace and 'force' is set to false,
                       the startup fails due to ongoing traces error. If the 'force' flag is set to true,
                       the startup first shuts down any ongoing traces and then continues with the startup,
                       default value is "True"
        :param str gnb_trace_profile: the id or name of the gNB (5G) start trace. user can get the gNB trace profile
                                      id or name details from `get_5g_profiles`.
        :param str enb_trace_profile: the id or name of the LTE (ENB) start trace. user can get the LTE trace profile
                                      id or name details from  `get_LTE_profiles`.
        :param str bts_trace_profile: the id or name of the BTS start trace. user can get the BTS trace profile
                                      id or name details from  `get_bts_profiles`.
        :param str vcu_trace_profile: the id or name of the vCU start trace. user can get the vCU trace profile
                                      id or name details from  `get_vcu_profiles`.
        :param str vdu_trace_profile: the id or name of the vDU start trace. user can get the vDU trace profile
                                      id or name details from  `get_vdu_profiles`.
        :param list gnb_custom_profile: The gNB (5G) custom profile name list of the start trace to be started.

                                         e.g : [pmFiles5g, condor5gSyslog, SCF5g,
                                         L2Ps_Component, L2Lo_Component, L2HiRlc_Component, L2HiPdcp_Component,
                                         L2Ps_Sherpa, L2Lo_Sherpa, L2HiRlc_Sherpa, L2HiPdcp_Sherpa,
                                         Tracer_5g,
                                         :ref:`l1IqTracer <l1IqTracer>`,
                                         :ref:`cp_5g <controlPlane5g>`,
                                         :ref:`controlPlane5g <controlPlane5g>`,
                                         :ref:`bip_interface_mirroring <bip_interface_mirroring>`,
                                         :ref:`L1stream <L1stream>`,
                                         :ref:`L2Ps_Component <L2Ps_Component>`]

        :param list enb_custom_profile: The LTE (ENB) custom profile name list of the start trace to be started.

                                         e.g : [lteTracer_4g, condor4gTti, condor4gAa, condor4gSyslog,
                                         pmFiles4g, scf4g, condor4gL2, l1Iq4g,
                                         :ref:`cp_4g <controlPlane4g>`,
                                         :ref:`controlPlane4g <controlPlane4g>`]

        :param list bts_custom_profile: The BTS custom profile name list of the start trace to be started.

                                         e.g : [scf, pmFiles,
                                         :ref:`rad <rad>`,
                                         :ref:`tss <tss>`,
                                         :ref:`immediateSnapshot <immediateSnapshot>`,
                                         :ref:`ipCapture <ipCapture>`,
                                         :ref:`screlBts <screlBts>`,
                                         :ref:`BTSeventBasedTracer <BTSeventBasedTracer>`]

        :param list vdu_custom_profile: The VDU custom profile name list of the start trace to be started.

                                         e.g : [snapshotVdu, tracerVdu, L2Ps_Component, L2Lo_Component,
                                         L2HiRlc_Component, L2HiPdcp_Component, L2Ps_Sherpa, L2Lo_Sherpa,
                                         L2HiRlc_Sherpa, L2HiPdcp_Sherpa,
                                         :ref:`L1StreamVdu <L1StreamVdu>`,
                                         :ref:`flowTracerVdu <controlPlane5gVdu>`
                                         :ref:`tssVdu <tssVdu>`,
                                         :ref:`controlPlane5gVdu <controlPlane5gVdu>`,
                                         :ref:`syslogVdu <syslogVdu>`,
                                         :ref:`l1IqVdu <l1IqVdu>`,
                                         :ref:`eventBasedTracerVdu <eventBasedTracerVdu>`,
                                         :ref:`screlVdu <screlVdu>`]

        :param list vcu_custom_profile: The VCU custom profile name list of the start trace to be started.
                                         e.g : [snapshotVcu, tracerVcu, L2Ps_Component, L2Lo_Component,
                                         L2HiRlc_Component, L2HiPdcp_Component, L2Ps_Sherpa, L2Lo_Sherpa,
                                         L2HiRlc_Sherpa, L2HiPdcp_Sherpa,
                                         :ref:`flowTracerVcu <controlPlane5gVcu>`
                                         :ref:`controlPlane5gVcu <controlPlane5gVcu>`,
                                         :ref:`syslogVcu <syslogVcu>`,
                                         :ref:`screlVcu <screlVcu>`]

        :param bool wait_for_activation: If user wants to confirm if the traces are started, and it is in "running"
                                    state. pass wait_for_activation=True
        :param str resource_group: 	you can pass "on-demand" or "inspector"
        :param bool allow_start_failures: If set to true trace will continue even on tracer errors, as long as one
                                          trace target is running. If set to false whole trace will fail if even single
                                          tracer fails. default value is "True"
        :param post_processors: (optional) by default false.
                                For emil decoding pass post_processors=True and emil_profile_values
                                The profiles can be "standard" Emil profile (like "5G L3") or custom, user created
                                profile? e.g. emil_profile_values='5G L3'

        :return: It returns start trace tracer_id
        """
        return connection.start_trace(tag=tag, duration=duration, bts=bts, timeout=int(timeout),
                                      resource_group=resource_group, allow_start_failures=allow_start_failures,
                                      force=force, **kwargs).to_dict()

